CREATE PROCEDURE dbo.Walk @n INT AS
BEGIN
    ;WITH s AS (SELECT 1 AS v) SELECT v FROM s;
    WHILE (@n > 0)
    BEGIN;
        SET @n = @n - 1;
    END;
    IF (@n = 0)
    BEGIN ;WITH t AS (SELECT 2 AS w) SELECT w FROM t;
    END
END
