  AND c7 < SOME (SELECT c7 FROM dbo.t2) AND c8 <= SOME (SELECT c8 FROM dbo.t2) AND c9 !< SOME (SELECT c9 FROM dbo.t2);
SELECT c1 FROM dbo.t1 WHERE c1 = ANY (SELECT c1 FROM dbo.t3) OR c2 > ANY (SELECT c2 FROM dbo.t3);

