DECLARE @tv TABLE (c1 int, c2 nvarchar(10), c3 int, c4 int, c5 int);
DELETE FROM dbo.t1 OUTPUT DELETED.*, DELETED.c1 AS old_c1, t2.c2, DELETED.c1 * 2 INTO @tv FROM dbo.t1 INNER JOIN dbo.t2 ON t1.c1 = t2.c1;
MERGE dbo.t1 AS t USING dbo.t2 AS s ON t.c1 = s.c1 WHEN MATCHED THEN UPDATE SET t.c2 = s.c2 OUTPUT $action, INSERTED.c2, s.c1 INTO dbo.t3 (act, c2, c1);

