UPDATETEXT t1.c1 @ptr 0 NULL t2.c2 @ptr2;

SELECT ALL TOP (10) PERCENT WITH TIES c1, c2 INTO dbo.t9 ON [PRIMARY] FROM dbo.t1 WHERE c1 > 0 ORDER BY c1 OPTION (RECOMPILE);
