SELECT a.c1 FROM dbo.t1 FOR SYSTEM_TIME AS OF '2024-01-01T00:00:00' AS a, dbo.t1 FOR SYSTEM_TIME AS OF @d0 AS g, dbo.t1 FOR SYSTEM_TIME FROM @d1 TO '2024-12-31' AS b, dbo.t1 FOR SYSTEM_TIME FROM '2024-01-01' TO @d2 AS f;
SELECT c.c1 FROM dbo.t1 FOR SYSTEM_TIME BETWEEN '2024-01-01' AND @d2 AS c, dbo.t1 FOR SYSTEM_TIME CONTAINED IN ('2024-01-01', '2024-06-01') AS d, dbo.t1 FOR SYSTEM_TIME ALL AS e;

