SELECT c1, COUNT(*) AS n FROM dbo.t1 WHERE c1 > @p1 AND c2 = @p2 GROUP BY c1 OPTION (HASH GROUP, LOOP JOIN, EXPAND VIEWS, FAST 10, FORCE ORDER, FORCE SCALEOUTEXECUTION, IGNORE_NONCLUSTERED_COLUMNSTORE_INDEX, KEEP PLAN, MAX_GRANT_PERCENT = 50, MIN_GRANT_PERCENT = 10, MAXDOP 4, NO_PERFORMANCE_SPOOL, OPTIMIZE FOR (@p1 UNKNOWN, @p2 = N'abc'), QUERYTRACEON 4199, ROBUST PLAN, USE HINT ('DISABLE_OPTIMIZED_NESTED_LOOP', 'FORCE_LEGACY_CARDINALITY_ESTIMATION'));
SELECT c1 FROM dbo.t1 UNION SELECT c1 FROM dbo.t2 OPTION (ORDER GROUP, CONCAT UNION, MERGE UNION, MERGE JOIN, HASH JOIN, KEEPFIXED PLAN, MAXRECURSION 100, OPTIMIZE FOR UNKNOWN, RECOMPILE, DISABLE SCALEOUTEXECUTION);

