WAITFOR DELAY '00:00:05';
WAITFOR TIME '22:30';
WAITFOR (RECEIVE TOP (1) conversation_handle, message_body FROM dbo.order_queue), TIMEOUT 5000;

KILL 53 WITH STATUSONLY;
KILL 'D5499C66-E398-45CA-BF7E-DC9C194B48CF' WITH STATUSONLY;
KILL 'D5499C66-E398-45CA-BF7E-DC9C194B48CF' COMMIT;

KILL 'D5499C66-E398-45CA-BF7E-DC9C194B48CF' ROLLBACK;
KILL QUERY NOTIFICATION SUBSCRIPTION ALL;
KILL QUERY NOTIFICATION SUBSCRIPTION 73;

CHECKPOINT 10;
RECONFIGURE WITH OVERRIDE;
SHUTDOWN WITH NOWAIT;

DECLARE c_iso INSENSITIVE SCROLL CURSOR FOR SELECT order_id FROM dbo.orders;
DECLARE c_iso2 CURSOR FOR SELECT order_id, status FROM dbo.orders FOR UPDATE OF status, order_id;
DECLARE c_ext CURSOR LOCAL FORWARD_ONLY STATIC READ_ONLY TYPE_WARNING FOR SELECT order_id FROM dbo.orders;

DECLARE c_g CURSOR GLOBAL SCROLL KEYSET SCROLL_LOCKS FOR SELECT order_id, status FROM dbo.orders FOR UPDATE OF status;
DECLARE c_d CURSOR LOCAL SCROLL DYNAMIC OPTIMISTIC FOR SELECT order_id FROM dbo.orders;
DECLARE c_f CURSOR FAST_FORWARD FOR SELECT order_id FROM dbo.orders;

OPEN GLOBAL c_orders;
FETCH NEXT FROM GLOBAL c_orders;
FETCH PRIOR FROM c_orders;

FETCH FIRST FROM c_orders;
FETCH LAST FROM c_orders;
FETCH ABSOLUTE 5 FROM c_orders;

FETCH RELATIVE -1 FROM c_orders;
CLOSE GLOBAL c_orders;
DEALLOCATE GLOBAL c_orders;

DECLARE @c CURSOR, @id int, @n int = 2;
OPEN @c;
FETCH ABSOLUTE @n FROM @c INTO @id;

DECLARE @c CURSOR;
CLOSE @c;
DEALLOCATE @c;

DECLARE @c CURSOR, @c2 CURSOR;
SET @c = CURSOR LOCAL FORWARD_ONLY STATIC READ_ONLY TYPE_WARNING FOR SELECT order_id FROM dbo.orders;
SET @c2 = CURSOR GLOBAL SCROLL KEYSET SCROLL_LOCKS FOR SELECT order_id, status FROM dbo.orders FOR UPDATE OF status;

DECLARE @c CURSOR, @c2 CURSOR;
SET @c = CURSOR DYNAMIC OPTIMISTIC FOR SELECT order_id FROM dbo.orders;
SET @c2 = CURSOR FAST_FORWARD FOR SELECT order_id FROM dbo.orders FOR READ ONLY;

DECLARE @c CURSOR, @c2 CURSOR;
SET @c = @c2;
SET @c2 = c_orders;

DECLARE @s nvarchar(50), @g geometry;
SET @s = N'abc' + N'def';
SET @g = geometry::STGeomFromText('POINT(1 2)', 0);

DECLARE @p Point;
SET @p.X = @p.X + 1.1;
SET @p = Point.SetXY(23.5, 23.5);

DECLARE @v int = 10;
SET @v += 1;
SET @v -= 2;

DECLARE @v int = 10;
SET @v *= 3;
SET @v /= 2;

DECLARE @v int = 10;
SET @v %= 7;
SET @v &= 6;

DECLARE @v int = 10;
SET @v ^= 3;
SET @v |= 8;

DECLARE @id int = 1, @name AS nvarchar(50) = N'abc', @cur CURSOR;
DECLARE @orders AS TABLE (
  order_id int NOT NULL PRIMARY KEY CLUSTERED WITH FILLFACTOR = 80,
  note nvarchar(100) COLLATE Latin1_General_CI_AS DEFAULT N'none',
  total AS order_id * 2,
  seq int IDENTITY(1, 1) NULL UNIQUE NONCLUSTERED WITH (PAD_INDEX = ON, FILLFACTOR = 90, IGNORE_DUP_KEY = OFF),
  qty int CHECK (qty > 0)
);

DECLARE @co TABLE (
  a int PRIMARY KEY WITH (COMPRESSION_DELAY = 0),
  b int UNIQUE WITH (COMPRESSION_DELAY = 10 MINUTES),
  c int UNIQUE WITH (DATA_COMPRESSION = COLUMNSTORE),
  d int UNIQUE WITH (DATA_COMPRESSION = COLUMNSTORE_ARCHIVE)
);

BULK INSERT sales.dbo.orders FROM 'D:\data\orders.csv' WITH (DATA_SOURCE = 'ds_files', CODEPAGE = 'RAW', DATAFILETYPE = 'char', FIELDTERMINATOR = ',', ORDER (order_id ASC, region DESC));
BULK INSERT dbo.orders FROM 'D:\data\orders.dat' WITH (CODEPAGE = 'ACP', DATAFILETYPE = 'widechar');
BULK INSERT orders FROM 'D:\data\orders.bin' WITH (CODEPAGE = 'OEM', DATAFILETYPE = 'native');

DISABLE TRIGGER dbo.trg_orders, dbo.trg_audit ON dbo.orders;
DISABLE TRIGGER ALL ON DATABASE;
DISABLE TRIGGER trg_logon ON ALL SERVER;

ENABLE TRIGGER dbo.trg_orders, dbo.trg_audit ON dbo.orders;
ENABLE TRIGGER ALL ON DATABASE;
ENABLE TRIGGER trg_logon ON ALL SERVER;

UPDATE STATISTICS dbo.orders ix_orders_date WITH FULLSCAN, PERSIST_SAMPLE_PERCENT = ON;
